// Release notes are markdown written on GitHub (often generated by `--generate-notes`). The page shows them without
// a markdown library and without v-html: headings, bullet lists and paragraphs as text, plus http(s) links. Anything
// else, HTML included, stays literal text and Vue escapes it.

export type NoteBlock
  = | { kind: 'heading', text: string }
    | { kind: 'list', items: string[] }
    | { kind: 'paragraph', text: string }

/** Drops emphasis markers (`**bold**`, `__x__`), which would otherwise show as literal characters. */
const plain = (line: string) => line.replace(/\*\*(.+?)\*\*/g, '$1').replace(/__(.+?)__/g, '$1').trim()

/** Blocks of one stretch of text between blank lines. */
function blocksOf(part: string): NoteBlock[] {
  const blocks: NoteBlock[] = []
  for (const line of part.split('\n')) {
    const heading = /^#{1,6}\s+(.*)$/.exec(line)
    const item = /^\s*[*-]\s+(.*)$/.exec(line)
    const last = blocks.at(-1)
    if (heading) {
      blocks.push({ kind: 'heading', text: plain(heading[1]!) })
    }
    else if (item && last?.kind === 'list') {
      last.items.push(plain(item[1]!))
    }
    else if (item) {
      blocks.push({ kind: 'list', items: [plain(item[1]!)] })
    }
    else if (line.trim() !== '' && last?.kind === 'paragraph') {
      last.text = `${last.text} ${plain(line)}`
    }
    else if (line.trim() !== '') {
      blocks.push({ kind: 'paragraph', text: plain(line) })
    }
  }
  return blocks
}

export function noteBlocks(markdown: string): NoteBlock[] {
  return markdown.replace(/\r\n/g, '\n').split(/\n\s*\n/).flatMap(blocksOf)
}

export interface InlinePart {
  text: string
  /** Only http(s) URLs become links. */
  href?: string
}

const LINK = /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)|(https?:\/\/[^\s)]+)/g

export function inlineParts(text: string): InlinePart[] {
  const parts: InlinePart[] = []
  let cursor = 0
  for (const match of text.matchAll(LINK)) {
    if (match.index > cursor) {
      parts.push({ text: text.slice(cursor, match.index) })
    }
    parts.push(match[1] ? { text: match[1], href: match[2] } : { text: match[3]!, href: match[3] })
    cursor = match.index + match[0].length
  }
  if (cursor < text.length) {
    parts.push({ text: text.slice(cursor) })
  }
  return parts
}
